#include <condition_variable>
#include <mutex>
#include <thread>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::mutex mutex;
    std::condition_variable condition;
    auto native = condition.native_handle();
    (void)native;
    std::condition_variable_any any;
    std::unique_lock<std::mutex> lock{mutex};
    assert(any.wait_for(lock, std::chrono::milliseconds(1)) == std::cv_status::timeout);
    std::once_flag flag;
    int count = 0;
    std::call_once(flag, [&] { ++count; });
    std::call_once(flag, [&] { ++count; });
    assert(count == 1);
}
